    private function readerEditionDropdown(array $edition,?string $readerUser=null): string
    {
        $publication=(string)($edition['publication_guid']??'');if(!Uuid::isValid($publication))return'';$city=(string)($edition['city_guid']??'');$language=(string)($edition['language_guid']??'');$activeSlug=(string)($edition['slug']??'');$date=(string)($edition['edition_date']??date('Y-m-d'));
        $historyLimit=max(30,min(1000,(int)TenantData::effectiveSetting('reader.edition_history_limit','365',$publication,$readerUser)));
        $rows=PublicReadCache::readerEditionHistory($publication,Uuid::isValid($city)?$city:null,Uuid::isValid($language)?$language:null,$historyLimit);if(count($rows)<2)return'';
        $current=\DateTimeImmutable::createFromFormat('!Y-m-d',$date)?:new \DateTimeImmutable('today');$months=[];foreach($rows as$row){$d=\DateTimeImmutable::createFromFormat('!Y-m-d',(string)$row['edition_date']);if(!$d)continue;$months[$d->format('Y-m')][]=['date'=>$d,'row'=>$row];}
        $html='<div class="reader-edition-menu-control" data-reader-edition-menu><button class="reader-header-tool reader-edition-trigger" type="button" data-reader-edition-trigger aria-haspopup="dialog" aria-expanded="false" aria-label="Choose back edition" title="Choose edition date">'.View::icon('calendar').'<span class="reader-edition-full-date">'.$this->e($current->format('d M Y')).'</span><span class="reader-edition-short-date">'.$this->e($current->format('d M')).'</span><span class="reader-edition-chevron">'.View::icon('chev-down').'</span></button><div class="reader-edition-menu hidden" data-reader-edition-panel role="dialog" aria-label="Back editions"><div class="reader-edition-menu-head"><div><span class="eyebrow">BACK EDITIONS</span><strong>'.$this->e((string)($edition['publication_name']??'Edition')).'</strong></div><a href="/archive">Full archive</a></div><div class="reader-edition-menu-scroll">';
        $first=true;foreach($months as$ym=>$items){$month=$items[0]['date'];$hasActive=false;foreach($items as$item)if((string)$item['row']['slug']===$activeSlug){$hasActive=true;break;}$html.='<section class="reader-edition-month'.($hasActive?' active':'').'"><div class="reader-edition-month-label">'.$this->e($month->format('F Y')).'</div><div class="reader-edition-date-list">';foreach($items as$item){$d=$item['date'];$row=$item['row'];$active=(string)$row['slug']===$activeSlug;$html.='<a class="reader-edition-choice'.($active?' active':'').'" href="/edition/'.$this->e((string)$row['slug']).'/page/1"'.($active?' aria-current="date"':'').' title="'.$this->e($d->format('l, d F Y')).'"><time datetime="'.$this->e($d->format('Y-m-d')).'"><strong>'.$this->e($d->format('d')).'</strong><span>'.$this->e($d->format('D')).'</span></time></a>';}$html.='</div></section>';$first=false;}
        return$html.'</div><div class="reader-edition-menu-foot"><span>Exact publication + city + language</span><a href="/archive">Older editions →</a></div></div></div>';
    }

    private function readerEditionStrip(array $edition): string
    {
        $publication=(string)($edition['publication_guid']??'');if(!Uuid::isValid($publication))return'';$city=(string)($edition['city_guid']??'');$language=(string)($edition['language_guid']??'');$date=(string)($edition['edition_date']??date('Y-m-d'));
        $rows=PublicReadCache::readerEditionCalendar($date,$publication,Uuid::isValid($city)?$city:null,Uuid::isValid($language)?$language:null,45);if(count($rows)<2)return'';
        $activeSlug=(string)($edition['slug']??'');$labelDate=\DateTimeImmutable::createFromFormat('!Y-m-d',$date)?:new \DateTimeImmutable('today');$html='<div class="reader-edition-switcher" data-reader-edition-switcher><div class="reader-edition-switcher-inner"><button class="reader-edition-scroll" type="button" data-edition-strip-scroll="-1" aria-label="Earlier editions">'.View::icon('chev-left').'</button><div class="reader-edition-context"><span>EDITION</span><strong>'.$this->e(strtoupper($labelDate->format('M Y'))).'</strong></div><nav class="reader-edition-dates" data-edition-date-rail aria-label="Switch edition date">';
        foreach($rows as$row){$d=\DateTimeImmutable::createFromFormat('!Y-m-d',(string)$row['edition_date']);if(!$d)continue;$active=(string)$row['slug']===$activeSlug;$html.='<a class="reader-edition-date'.($active?' active':'').'" href="/edition/'.$this->e((string)$row['slug']).'/page/1"'.($active?' aria-current="date"':'').' title="'.$this->e($d->format('l, d F Y')).'"><span>'.$this->e(strtoupper($d->format('D'))).'</span><strong>'.$this->e($d->format('d')).'</strong><small>'.$this->e(strtoupper($d->format('M'))).'</small></a>';}
        return$html.'</nav><button class="reader-edition-scroll" type="button" data-edition-strip-scroll="1" aria-label="Later editions">'.View::icon('chev-right').'</button></div></div>';
    }

    private function editionCoverUrl(array $edition,string $preferred='THUMB'): ?string
    {
        $preferred=strtolower($preferred);
        // Listing/newsstand surfaces are strict-thumbnail by design. Never escalate a
        // 170–420px cover card to PREVIEW/HIGHRES merely because a thumbnail is missing.
        $order=match($preferred){'thumb'=>['thumb'],'preview'=>['preview','thumb'],'highres'=>['highres','preview'],default=>['thumb']};
        foreach($order as$prefix){$guid=(string)($edition[$prefix.'_asset_guid']??'');if($guid!==''&&Uuid::isValid($guid))return '/media/'.Media::token($guid,86400);}
        return null;
    }

    private function joinedPageAsset(array $page,string $type): ?array
    {
        $prefix=strtolower($type);$guid=(string)($page[$prefix.'_asset_guid']??'');if($guid===''||!Uuid::isValid($guid))return null;
        return[
            'asset_guid'=>$guid,
            'storage_path'=>$page[$prefix.'_storage_path']??null,
            'byte_size'=>(int)($page[$prefix.'_byte_size']??0),
            'mime_type'=>$page[$prefix.'_mime_type']??null,
        ];
    }

    private function pageVisual(string $editionGuid,int $pageNo,string $type): ?string
    {
        $p=TenantData::pageWithAssets($editionGuid,$pageNo);if(!$p)return null;$a=$this->joinedPageAsset($p,$type)??$this->joinedPageAsset($p,'PREVIEW')??$this->joinedPageAsset($p,'HIGHRES');return$a?'/media/'.Media::token($a['asset_guid'],86400):null;
    }

    private function readerState(string $slug,int $pageNo): never
    {
        $cacheKey='reader:state:v2:'.RequestContext::tenantGuid().':'.hash('sha256',$slug).':'.$pageNo;
        try{
            $cached=RedisStore::getJson($cacheKey);
            if(is_array($cached)&&!empty($cached['ok'])){header('X-Reader-State-Cache: HIT');Http::json($cached);}
        }catch(\Throwable){}
        $manifest=EditionManifest::bySlug($slug);$ed=$manifest['edition']??null;if(!$ed||($ed['status']??'')!=='PUBLISHED')Http::json(['ok'=>false,'code'=>'EDITION_NOT_FOUND'],404);$p=EditionManifest::page($manifest,$pageNo);if(!$p)Http::json(['ok'=>false,'code'=>'PAGE_NOT_FOUND'],404);$high=$this->joinedPageAsset($p,'HIGHRES')??$this->joinedPageAsset($p,'PREVIEW');$preview=$this->joinedPageAsset($p,'PREVIEW')??$high;$thumb=$this->joinedPageAsset($p,'THUMB');$highUrl=$high?'/media/'.Media::token($high['asset_guid'],86400):null;$previewUrl=$preview?'/media/'.Media::token($preview['asset_guid'],86400):$highUrl;
        $data=['ok'=>true,'edition_guid'=>$ed['edition_guid'],'slug'=>$slug,'page_guid'=>$p['page_guid'],'page_number'=>$pageNo,'page_count'=>(int)$ed['page_count'],'width'=>(int)$p['width'],'height'=>(int)$p['height'],'image'=>$highUrl,'highres'=>$highUrl,'preview'=>$previewUrl,'thumbnail'=>$thumb?'/media/'.Media::token($thumb['asset_guid'],86400):null,'preview_asset_guid'=>$preview['asset_guid']??null,'highres_asset_guid'=>$high['asset_guid']??null,'tiles'=>'/api/v1/pages/'.$p['page_guid'].'/tiles','prev'=>$pageNo>1?$pageNo-1:null,'next'=>$pageNo<(int)$ed['page_count']?$pageNo+1:null];
        try{RedisStore::setJson($cacheKey,$data,RedisStore::ttlWithJitter(300,30));}catch(\Throwable){}header('X-Reader-State-Cache: MISS');Http::json($data);
    }

    private function tileManifest(string $pageGuid): never
    {
        $row=MultiLayerCache::remember('tile-manifest-meta:'.$pageGuid,21600,86400,fn()=>Store::one('SELECT a.storage_path,p.width,p.height FROM ep_page_assets a JOIN ep_pages p ON p.page_guid=a.page_guid WHERE a.tenant_guid=? AND a.page_guid=? AND a.asset_type="TILE_MANIFEST"',[TenantData::tenantBin(),Uuid::toBinary($pageGuid)]));if(!$row)Http::json(['ok'=>true,'tiles_available'=>false],200);$full=dirname(__DIR__,2).'/storage/'.ltrim($row['storage_path'],'/');if(!is_file($full))Http::json(['ok'=>true,'tiles_available'=>false]);$d=json_decode(file_get_contents($full),true)?:[];$d['tiles_available']=true;$d['tile_url_template']='/api/v1/pages/'.$pageGuid.'/tiles/{level}/{x}/{y}.webp';Http::json($d);
    }

    private function tile(string $pageGuid,int $level,int $x,int $y): never
    {
        $row=MultiLayerCache::remember('tile-manifest-path:'.$pageGuid,21600,86400,fn()=>Store::one('SELECT storage_path FROM ep_page_assets WHERE tenant_guid=? AND page_guid=? AND asset_type="TILE_MANIFEST"',[TenantData::tenantBin(),Uuid::toBinary($pageGuid)]));if(!$row){http_response_code(404);exit;}$manifest=dirname(__DIR__,2).'/storage/'.ltrim($row['storage_path'],'/');$file=dirname($manifest).'/level-'.$level.'/'.$x.'_'.$y.'.webp';if(!is_file($file)){http_response_code(404);exit;}header('Content-Type: image/webp');Http::immutable(86400);readfile($file);exit;
    }

    private function articleAt(string $pageGuid): never
    {
        $p=Store::one('SELECT width,height FROM ep_pages WHERE tenant_guid=? AND page_guid=?',[TenantData::tenantBin(),Uuid::toBinary($pageGuid)]);if(!$p)Http::json(['ok'=>false,'code'=>'PAGE_NOT_FOUND'],404);$x=max(0,min(1,(float)($_GET['x']??0)));$y=max(0,min(1,(float)($_GET['y']??0)));$px=(int)round($x*$p['width']);$py=(int)round($y*$p['height']);$blocks=Store::all('SELECT block_guid,text_content,x1,y1,x2,y2 FROM ep_ocr_blocks WHERE tenant_guid=? AND page_guid=? AND x1<=? AND x2>=? AND y1<=? AND y2>=? ORDER BY (x2-x1)*(y2-y1) LIMIT 12',[TenantData::tenantBin(),Uuid::toBinary($pageGuid),$px,$px,$py,$py]);$text=trim(implode("\n",array_column($blocks,'text_content')));Http::json(['ok'=>(bool)$blocks,'page_guid'=>$pageGuid,'text'=>$text,'blocks'=>array_map(fn($b)=>['block_guid'=>$this->guid($b['block_guid']),'text'=>$b['text_content'],'bbox'=>[(int)$b['x1'],(int)$b['y1'],(int)$b['x2'],(int)$b['y2']]],$blocks)]);
    }
